using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Staff of Power (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class StaffOfPower2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("staff-of-power", null, 0, MagicItemType.Staff, ItemRarity.VeryRare, true, ContentSource.Srd51,
			Charges(20, ItemRecharge.LongRest, "2d8+4", Effect(MagicEffectKind.AttackAndDamage, 2), Effect(MagicEffectKind.ArmorClass, 2), Effect(MagicEffectKind.SavingThrows, 2), Effect(MagicEffectKind.SpellAttack, 2)),
			("Bastone del potere", "Bastone, molto raro (richiede sintonia con un mago, uno stregone o un warlock)",
			"Questo bastone può essere impugnato come un bastone ferrato magico che garantisce un bonus di +2 ai tiri per colpire e ai tiri per i danni effettuati con esso. Mentre il personaggio lo impugna, ottiene un bonus di +2 alla Classe Armatura, ai tiri salvezza e ai tiri per colpire con incantesimo.\n\nIl bastone possiede 20 cariche per le proprietà descritte di seguito. All'alba di ogni giorno, il bastone recupera 2d8 + 4 cariche consumate. Se il personaggio consuma l'ultima carica, deve tirare un d20; se ottiene 1, il bastone mantiene il suo bonus +2 ai tiri per colpire e ai tiri per i danni ma perde le sue altre proprietà; se ottiene 20, recupera 1d8 + 2 cariche.\n\n***Colpo poderoso.*** Quando il personaggio colpisce con un attacco in mischia usando il bastone, può consumare 1 carica per infliggere 1d6 danni da forza extra al bersaglio.\n\n***Incantesimi.*** Mentre il personaggio lo impugna, può usare un'azione per consumare 1 o più delle sue cariche e lanciare uno dei seguenti incantesimi usando la CD del tiro salvezza sull'incantesimo e il bonus di attacco dell'incantesimo: *blocca mostri* (5 cariche), *cono di freddo* (5 cariche), *dardo incantato* (1 carica), *fulmine* (versione di 5° livello, 5 cariche), *globo di invulnerabilità* (6 cariche), *levitazione* (2 cariche), *muro di forza* (5 cariche), *palla di fuoco* (versione di 5° livello, 5 cariche) o *raggio di affaticamento* (1 carica).\n\n***Colpo del castigo.*** Il personaggio può usare un'azione per spezzare il bastone sul ginocchio o contro una superficie solida ed effettuare un colpo del castigo. Il bastone è distrutto e sprigiona la magia che gli restava in un'esplosione che si espande fino a riempire una sfera del raggio di 9 metri centrata su di esso.\n\nIl personaggio ha una probabilità del 50% di spostarsi istantaneamente su un piano di esistenza casuale per evitare l'esplosione. Se non riesce a evitare l'effetto, subisce danni da forza pari a 16 × il numero di cariche rimanenti nel bastone. Ogni altra creatura nell'area deve effettuare un tiro salvezza su Destrezza con CD 17: se lo fallisce, subisce un ammontare di danni basato sulla sua distanza dal punto di origine dell'esplosione, come indicato nella tabella sottostante. Ogni creatura che supera il tiro salvezza subisce soltanto la metà di quei danni.\n\n| Distanza dall'origine | Danni |\n|---|---|\n| 3 m o meno | 8 × il numero di cariche nel bastone |\n| Più di 3 m, fino a 6 m | 6 × il numero di cariche nel bastone |\n| Più di 6 m, fino a 9 m | 4 × il numero di cariche nel bastone |", null),
			("Staff of Power", "Staff, very rare (requires attunement by a sorcerer, warlock, or wizard)",
			"This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. While holding it, you gain a +2 bonus to Armor Class, saving throws, and spell attack rolls.\n\nThe staff has 20 charges for the following properties. The staff regains 2d8 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, the staff retains its +2 bonus to attack and damage rolls but loses all other properties. On a 20, the staff regains 1d8 + 2 charges.\n\n***Power Strike.*** When you hit with a melee attack using the staff, you can expend 1 charge to deal an extra 1d6 force damage to the target.\n\n***Spells.*** While holding this staff, you can use an action to expend 1 or more of its charges to cast one of the following spells from it, using your spell save DC and spell attack bonus: cone of cold (5 charges), fireball (5th-level version, 5 charges), globe of invulnerability (6 charges), hold monster (5 charges), levitate (2 charges), lightning bolt (5th-level version, 5 charges), magic missile (1 charge), ray of enfeeblement (1 charge), or wall of force (5 charges).\n\n***Retributive Strike.*** You can use an action to break the staff over your knee or against a solid surface, performing a retributive strike. The staff is destroyed and releases its remaining magic in an explosion that expands to fill a 30-foot-radius sphere centered on it.\n\nYou have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take force damage equal to 16 × the number of charges in the staff. Every other creature in the area must make a DC 17 Dexterity saving throw. On a failed save, a creature takes an amount of damage based on how far away it is from the point of origin, as shown in the following table. On a successful save, a creature takes half as much damage.\n\n| Distance from Origin | Damage |\n|---|---|\n| 10 ft. away or closer | 8 × the number of charges in the staff |\n| 11 to 20 ft. away | 6 × the number of charges in the staff |\n| 21 to 30 ft. away | 4 × the number of charges in the staff |", null));
	}
}
